const start = new Date($json.PROJECT_START_DATE + 'T00:00:00+02:00');
const now = new Date();
const projectDay = Math.floor((now - start) / (24 * 60 * 60 * 1000)) + 1;

return [{
  json: {
    ...$json,
    PROJECT_DAY: projectDay
  }
}];

let text = ($json.choices?.[0]?.message?.content || '').trim();

const followBlock = `Follow ForgeView:

X:
https://x.com/ForgeViewX

YouTube:
https://youtube.com/@ForgeViewGrowth`;

if (!text.includes('https://x.com/ForgeViewX') || !text.includes('https://youtube.com/@ForgeViewGrowth')) {
  text = text.replace(/Follow ForgeView:[\s\S]*$/i, '').trim();
  text = `${text}\n\n${followBlock}`;
}

return [{
  json: {
    telegram_public_channel: $('Set ForgeView Config').item.json.TELEGRAM_PUBLIC_CHANNEL,
    telegram_post: text
  }
}];

let post = ($json.choices?.[0]?.message?.content || '').trim();
post = post.replace(/^[`'"“”]+|[`'"“”]+$/g, '').trim();

const upload = $('Format YouTube Upload Confirmation').item.json;
const config = $('Set ForgeView Config').item.json;
const youtubeUrl = upload.video_url;

post = post.replace(/Follow ForgeView:[\s\S]*$/i, '').trim();
if (youtubeUrl && youtubeUrl !== 'URL unavailable' && !post.includes(youtubeUrl)) {
  post = `${post}\n\n${youtubeUrl}`;
}
if (!post.includes('https://t.me/ForgeViewCom')) {
  post = `${post}\n\nTelegram: https://t.me/ForgeViewCom`;
}

const message = `X DRAFT - POST MANUALLY\n\n${post}\n\nAccount: ${config.X_ACCOUNT}`;

return [{
  json: {
    x_post: post,
    x_draft_message: message,
    x_drafts_chat_id: config.X_DRAFTS_TELEGRAM_CHAT_ID,
    youtube_url: youtubeUrl
  }
}];

let raw = ($json.choices?.[0]?.message?.content || '').trim();
const config = $('Set ForgeView Config').item.json;

const requiredDescriptionBlock = `#Shorts\n\nTelegram:\nhttps://t.me/ForgeViewCom\n\nX:\nhttps://x.com/ForgeViewX`;

function stripJsonFence(value) {
  return String(value || '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

function compactSentence(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function splitNarration(parsed) {
  if (Array.isArray(parsed.scene_narrations) && parsed.scene_narrations.length >= 7) {
    return parsed.scene_narrations.slice(0, 7).map(compactSentence);
  }
  const script = compactSentence(parsed.narration_script || '');
  const sentences = script.match(/[^.!?]+[.!?]+/g) || [];
  if (sentences.length >= 7) return sentences.slice(0, 7).map(compactSentence);
  const out = [];
  for (let i = 1; i <= 7; i++) out.push(compactSentence(parsed[`scene${i}`] || `ForgeView system scene ${i}.`));
  return out;
}

function buildVideoPrompts(parsed, sceneNarrations) {
  if (Array.isArray(parsed.video_prompts) && parsed.video_prompts.length >= 7) {
    return parsed.video_prompts.slice(0, 7).map((prompt, index) => {
      const narration = sceneNarrations[index];
      let text = compactSentence(prompt);
      if (!text.toLowerCase().includes(narration.toLowerCase().slice(0, 24))) {
        text = `Narration content: ${narration}. ${text}`;
      }
      return `${text} Consistent ForgeView visual style: dark cinematic black charcoal environment, yellow ForgeView accent lighting, anonymous founder protagonist, same character across every scene, high production value, slow camera movement, no readable text, no letters, no logos, no UI screenshots, no watermarks.`;
    });
  }

  return sceneNarrations.map((narration, index) =>
    `Scene ${index + 1}. Narration content: ${narration}. Visualize this exact idea with the same anonymous founder protagonist in a dark cinematic black charcoal ForgeView automation environment, yellow accent lighting, dramatic film still, strong foreground subject, slow camera movement, no readable text, no letters, no logos, no UI screenshots, no watermarks.`
  );
}

let parsed;
try {
  parsed = JSON.parse(stripJsonFence(raw));
} catch (e) {
  throw new Error(`Shorts draft OpenAI output was not valid JSON: ${e.message}`);
}

parsed.title = compactSentence(parsed.title || 'ForgeView Cinematic Automation Lesson #Shorts');
parsed.description = String(parsed.description || '').replace(/Follow ForgeView:[\s\S]*$/i, '').trim();
for (const line of requiredDescriptionBlock.split('\n')) {
  if (line && !parsed.description.includes(line)) parsed.description += `\n${line}`;
}
parsed.description = parsed.description.replace(/\n{3,}/g, '\n\n').trim();
parsed.scene_narrations = splitNarration(parsed);
parsed.narration_script = parsed.scene_narrations.join('\n');
for (let i = 1; i <= 7; i++) {
  if (!parsed[`scene${i}`]) parsed[`scene${i}`] = parsed.scene_narrations[i - 1].split(' ').slice(0, 6).join(' ');
}
if (!Array.isArray(parsed.tags)) {
  parsed.tags = ['AI automation', 'n8n', 'build in public', 'workflow reliability', 'ForgeViewAI'];
}
parsed.video_prompts = buildVideoPrompts(parsed, parsed.scene_narrations);

raw = JSON.stringify(parsed, null, 2);

const message = `CINEMATIC SHORTS PACKAGE DEBUG\n\n${raw}\n\nProject: ${config.BRAND_NAME}`;

return [{
  json: {
    shorts_raw: raw,
    shorts_json: parsed,
    shorts_message: message,
    x_drafts_chat_id: config.X_DRAFTS_TELEGRAM_CHAT_ID
  }
}];

const config = $('Set ForgeView Config').item.json;
const draft = $('Format Shorts Draft').item.json;

function stripJsonFence(value) {
  return String(value || '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

let shortsJson = draft.shorts_json;
if (!shortsJson) {
  try {
    shortsJson = JSON.parse(stripJsonFence(draft.shorts_raw));
  } catch (error) {
    throw new Error(`Shorts draft is not valid JSON: ${error.message}`);
  }
}

let title = String(shortsJson.title || 'ForgeView Automation Lesson #Shorts').replace(/\s+/g, ' ').trim();
if (!/#Shorts/i.test(title)) title = `${title} #Shorts`;
if (title.length > 100) title = title.slice(0, 97).trimEnd() + '...';

let description = String(shortsJson.description || '').trim();
if (!description) {
  description = 'A ForgeView build-in-public lesson from AI automation, trading bots, and workflow reliability.';
}
const requiredDescriptionBlock = `#Shorts\n\nTelegram:\nhttps://t.me/ForgeViewCom\n\nX:\nhttps://x.com/ForgeViewX`;
for (const line of requiredDescriptionBlock.split('\n')) {
  if (line && !description.includes(line)) description += `\n${line}`;
}
description = description.replace(/\n{3,}/g, '\n\n').trim();

const tags = Array.isArray(shortsJson.tags)
  ? shortsJson.tags.map(String).filter(Boolean)
  : ['AI automation', 'trading bots', 'n8n', 'build in public', 'ForgeViewAI'];
const narrationScript = String(shortsJson.narration_script || '').trim();
const sceneNarrations = Array.isArray(shortsJson.scene_narrations) ? shortsJson.scene_narrations.slice(0, 7).map(String) : [];
const videoPrompts = Array.isArray(shortsJson.video_prompts) ? shortsJson.video_prompts.slice(0, 7) : [];

return [{
  json: {
    draft_chat_id: config.X_DRAFTS_TELEGRAM_CHAT_ID,
    youtube_channel_handle: '@ForgeViewGrowth',
    privacyStatus: 'public',
    publish_mode: 'draft_only',
    kling_preview_mode: true,
    video_provider: 'kling_text_to_video',
    estimated_cost_usd: 2.94,
    categoryId: '28',
    title,
    description,
    tags,
    tags_text: tags.join(', '),
    narration_script: narrationScript,
    scene_narrations: sceneNarrations,
    video_prompts: videoPrompts,
    shorts_json: shortsJson,
    video_provider_config_path: 'D:\\ForgeViewAI\\content\\config\\video_provider_config.json',
    local_project_root: 'D:\\ForgeViewAI',
    shorts_generator_dir: 'D:\\ForgeViewAI\\content\\video\\shorts-generator',
    output_path: 'D:\\ForgeViewAI\\output\\media\\videos\\draft.mp4'
  }
}];

const prepared = $('Prepare Shorts Generator Payload').item.json;
const bridgeConfig = $('Validate Bridge URL').item.json;
const bridge = $json || {};
let videoUrl = bridge.video_url || bridge.download_url || bridge.mp4_url;

if (!bridge.ok && bridge.error) {
  throw new Error(bridge.error);
}

if (!videoUrl) {
  throw new Error('Local Shorts Generator bridge did not return video_url/download_url/mp4_url for the generated MP4.');
}

if (/^http:\/\/(localhost|127\.0\.0\.1):/i.test(videoUrl)) {
  const bridgeUrl = bridgeConfig.bridge_url;
  if (!bridgeUrl || bridgeUrl.includes('FORGEVIEW_BRIDGE_URL')) {
    throw new Error('BRIDGE URL NOT CONFIGURED');
  }
  videoUrl = bridgeUrl.replace(/\/forgeview\/render-short\/?$/, '/files/draft.mp4');
}

return [{
  json: {
    ...prepared,
    bridge_status: bridge.status || (bridge.ok ? 'ok' : 'unknown'),
    bridge_message: bridge.message || '',
    bridge_video_path: bridge.video_path || '',
    generated_video_url: videoUrl,
    video_provider: bridge.video_provider || prepared.video_provider || 'unknown',
    configured_video_provider: bridge.configured_video_provider || 'unknown',
    provider_warnings: bridge.provider_warnings || [],
    estimated_cost_usd: Number(bridge.estimated_cost_usd || prepared.estimated_cost_usd || 0),
    publish_mode: bridge.publish_mode || prepared.publish_mode || 'draft_only',
    kling_preview_mode: bridge.kling_preview_mode !== undefined ? !!bridge.kling_preview_mode : true,
    kling_task_ids: bridge.kling_task_ids || [],
    kling_clip_paths: bridge.kling_clip_paths || [],
    narration_used: !!bridge.narration_used,
    background_music_used: !!bridge.background_music_used,
    subtitles_burned_in: !!bridge.subtitles_burned_in
  }
}];

const upload = $json;
const prepared = $('Prepare Shorts Generator Payload').item.json;
const videoId = upload.id || upload.videoId || upload.snippet?.resourceId?.videoId || '';
const url = videoId ? `https://www.youtube.com/shorts/${videoId}` : 'URL unavailable';

return [{
  json: {
    draft_chat_id: prepared.draft_chat_id,
    video_id: videoId,
    video_url: url,
    privacyStatus: 'public',
    title: prepared.title,
    description: prepared.description,
    tags: prepared.tags,
    tags_text: prepared.tags_text,
    confirmation_text: `UPLOAD SUCCESS\n\nVideo ID:\n${videoId || 'unknown'}\n\nURL:\n${url}\n\nPrivacy:\npublic`
  }
}];

